WITH exploded AS (SELECT id, plan, effective_from, currency, EXPLODE(discounts) AS tier_value FROM price_tiers), filtered AS (SELECT id, plan, effective_from, currency, tier_value, DATE_FORMAT(effective_from, 'MMM yyyy') AS effective_from_label FROM exploded WHERE tier_value BETWEEN 71 AND 75), filtered_price_tiers AS (SELECT *, INITCAP(TRIM(plan)) AS plan_title FROM filtered WHERE plan = 'basic'), filtered_price_tiers_2 AS (SELECT id, plan, effective_from, currency, effective_from_label, plan_title, CASE WHEN plan = 'enterprise' THEN 1 ELSE 0 END AS is_enterprise, LOWER(currency) AS currency_lower FROM filtered_price_tiers WHERE effective_from >= TO_DATE('2024-02-28') AND currency IN ('EUR', 'USD')), remaining_keys AS (SELECT plan, id FROM filtered_price_tiers_2 INTERSECT ALL SELECT plan, id FROM price_tiers WHERE plan = 'basic'), kept_rows AS (SELECT s.* FROM filtered_price_tiers_2 s JOIN remaining_keys k ON s.plan = k.plan AND s.id = k.id) SELECT plan, DATE_TRUNC('MONTH', effective_from) AS activity_month, COUNT(CASE WHEN plan = 'pro' THEN 1 END) AS pro_count, SUM(CASE WHEN currency = 'THB' THEN is_enterprise ELSE 0 END) AS thb_is_enterprise, COUNT(CASE WHEN currency = 'THB' THEN 1 END) AS thb_count, GROUPING(plan) AS gid FROM kept_rows GROUP BY ROLLUP (plan, DATE_TRUNC('MONTH', effective_from)) ORDER BY thb_count DESC
